from typing import List

def total_persistence_layercake(deaths: List[int], horizon: int) -> int:
    """Total H0 persistence via the layer-cake identity: sum_d min(d, T)."""
    return sum(min(d, horizon) for d in deaths)

algorithms.pseudocode:
function TOTAL_PERSISTENCE_LAYERCAKE(D: multiset of nat, T: nat) -> nat:
    total := 0
    for each d in D (with multiplicity):
        total := total + min(d, T)
    return total

# MST Law corollary: if for all d in D, d <= T then result = sum(D).

