def demo_layer_cake(deaths: List[int]) -> None:
    for T in [0, 3, 5, 8, 10]:
        lhs = sum(sum(1 for d in deaths if t < d) for t in range(T))
        rhs = sum(min(d, T) for d in deaths)
        print(f'T={T:2d}: lhs={lhs:2d} rhs={rhs:2d} '
              f"{'OK' if lhs == rhs else 'MISMATCH'}")

if __name__ == '__main__':
    demo_layer_cake([2, 3, 3, 7])

from itertools import combinations
from typing import Dict, List, Tuple

Edge = Tuple[int, int, int]

def kruskal_deaths(n: int, edges: List[Edge]) -> List[int]:
    label: Dict[int, int] = {v: v for v in range(n)}
    def rep(x: int) -> int:
        while label[x] != x:
            label[x] = label[label[x]]; x = label[x]
        return x
    deaths: List[int] = []
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        if rep(u) != rep(v):
            deaths.append(w); label[rep(u)] = rep(v)
    return deaths

def spans(n: int, edges: List[Edge], s: Tuple[int, ...]) -> bool:
    label = list(range(n))
    def rep(x: int) -> int:
        while label[x] != x:
            label[x] = label[label[x]]; x = label[x]
        return x
    for i in s:
        u, v, _ = edges[i]; label[rep(u)] = rep(v)
    return len({rep(v) for v in range(n)}) == 1

def demo() -> None:
    edges = [(0,1,1),(1,2,2),(2,3,3),(0,2,4),(0,3,5),(1,3,6)]
    n = 4
    deaths = kruskal_deaths(n, edges)
    T = max(deaths)
    persistence = sum(min(d, T) for d in deaths)
    mst = min(sum(edges[i][2] for i in s)
              for r in range(n-1, len(edges)+1)
              for s in combinations(range(len(edges)), r) if spans(n, edges, s))
    print('deaths =', sorted(deaths))
    print('persistence =', persistence, ' death-sum =', sum(deaths), ' MST =', mst)
    print('all equal:', persistence == sum(deaths) == mst)

if __name__ == '__main__':
    demo()

from typing import List

def beta0(deaths: List[int], t: int) -> int:
    return 1 + sum(1 for d in deaths if t < d)

def demo(deaths: List[int]) -> None:
    curve = [(t, beta0(deaths, t)) for t in range(max(deaths) + 2)]
    print('t     :', ' '.join(f'{t:2d}' for t, _ in curve))
    print('beta0 :', ' '.join(f'{b:2d}' for _, b in curve))
    print('monotone:', all(curve[i][1] >= curve[i+1][1]
                           for i in range(len(curve)-1)))
    print('beta0(max D) =', beta0(deaths, max(deaths)), '(expected 1)')

if __name__ == '__main__':
    demo([2, 2, 5, 9])
